function settingsV14(){const options=personalGoals.map(goal=>`<option value="${goal}" ${profile.personalGoal===goal?"selected":""}>${goal}</option>`).join("");app.insertAdjacentHTML("beforeend",`<div class="overlay"><section class="modal"><h2>Mes réglages</h2><label>Parcours</label><div class="choice"><button data-program="walk" class="${profile.program==="walk"?"on":""}">🚶<br>Marche Active</button><button data-program="run" class="${profile.program==="run"?"on":""}">🏃<br>Discovery Run</button></div><label for="personal-goal">Mon objectif</label><select class="goal-select" id="personal-goal"><option value="">Choisir un objectif…</option>${options}</select><p class="goal-settings-note">Cet objectif remplacera la troisième action complémentaire.</p><button class="primary save-settings">ENREGISTRER</button><div class="settings-tools"><button class="secondary export-settings">SAUVEGARDER MES DONNÉES</button><label class="secondary restore-settings" for="restore-settings">RESTAURER MES DONNÉES</label><input id="restore-settings" hidden type="file" accept="application/json"><button class="secondary about-settings">À PROPOS</button></div><button class="secondary close">ANNULER</button><button class="secondary reset">EFFACER MA PROGRESSION</button></section></div>`);const modal=app.querySelector(".overlay"),select=modal.querySelector("#personal-goal");modal.querySelectorAll("[data-program]").forEach(button=>button.onclick=()=>{profile.program=button.dataset.program;modal.querySelectorAll("[data-program]").forEach(item=>item.classList.toggle("on",item===button))});modal.querySelector(".save-settings").onclick=()=>{if(!select.value){toast("Choisis d’abord ton objectif");return}profile.personalGoal=select.value;save();render();toast("Objectif enregistré")};modal.querySelector(".export-settings").onclick=exportData;modal.querySelector("#restore-settings").onchange=event=>event.target.files[0]&&restore(event.target.files[0]);modal.querySelector(".about-settings").onclick=about;modal.querySelector(".close").onclick=render;modal.querySelector(".reset").onclick=()=>{if(confirm("Effacer toute la progression Discovery UP sur cet appareil ?")){Object.keys(localStorage).filter(key=>key.startsWith("discovery-up-")).forEach(key=>localStorage.removeItem(key));location.reload()}}}
