function celebrate(){const pieces=Array.from({length:24},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${(i%6)*.05}s"></i>`).join("");document.body.insertAdjacentHTML("beforeend",`<div class="confetti">${pieces}</div>`);setTimeout(()=>document.querySelector(".confetti")?.remove(),1500)}
function summary(){const d=data(),lv=levelInfo(),score=points(d),series=streak();d.finished=true;write(new Date(),d);app.insertAdjacentHTML("beforeend",`<div class="overlay"><section class="modal" style="text-align:center"><img class="pulse" src="${pulse(lv.number)}" alt="Pulse célèbre"><span class="mission-tag">+${score} ACTION${score>1?"S":""} VALIDÉE${score>1?"S":""}</span><h2>${series===1?"Une nouvelle série commence !":`${series} jours en mouvement !`}</h2><p>Ta progression reste acquise, jour après jour.</p><p>${lv.next?`Encore ${lv.next[1]-lv.total} points avant ${lv.next[0]}.`:"Tu as atteint Terrain solide."}</p><button class="primary close-summary">À DEMAIN</button><button class="secondary edit-summary">MODIFIER MA JOURNÉE</button></section></div>`);celebrate();app.querySelector(".close-summary").onclick=render;app.querySelector(".edit-summary").onclick=render}
function openBag(){if(!profile.bagReady||profile.drinkAvailable)return;profile.drinkAvailable=true;profile.bagReady=false;profile.bagCycleDays=[];profile.earnedBags=(profile.earnedBags||0)+1;save();const sparks=Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join("");app.insertAdjacentHTML("beforeend",`<div class="overlay reward-overlay"><section class="modal reward-modal"><div class="reward-stage"><span class="reward-halo"></span><span class="reward-sparks" aria-hidden="true">${sparks}</span><img class="reward-bag" src="./assets/rewards/bag-ready.webp" alt="Sac de sport ouvert"><img class="drink-reward" src="./assets/rewards/sports-drink.webp" alt="Boisson du sportif"></div><div class="reward-copy"><span class="mission-tag">RÉCOMPENSE DÉBLOQUÉE</span><h2>Boisson du sportif</h2><p>Elle protégera automatiquement une seule journée oubliée. Elle ne valide pas une activité et ne donne aucun point.</p><button class="primary close-reward">AJOUTER À MON INVENTAIRE</button></div></section></div>`);celebrate();navigator.vibrate?.([60,40,90]);app.querySelector(".close-reward").onclick=render}
function about(){app.insertAdjacentHTML("beforeend",`<div class="overlay"><section class="modal"><img class="brand" src="./logo-discovery-up.svg" alt="Discovery UP"><h2>Un mouvement chaque jour</h2><p>Le mouvement entretient ta série. Tes actions de renforcement, récupération, alimentation et ton objectif personnel construisent ta progression globale.</p><p>Une interruption ne retire aucun point et ne fait jamais perdre de niveau. Chaque reprise est une victoire.</p><div class="signature"><span>une application de</span><img src="./assets/discovery-sports.webp" alt="Discovery Sports"></div><button class="primary close">FERMER</button></section></div>`);app.querySelector(".close").onclick=render}
function exportData(){const items={};Object.keys(localStorage).filter(k=>k.startsWith("discovery-up-")).forEach(k=>items[k]=localStorage.getItem(k));const a=document.createElement("a"),url=URL.createObjectURL(new Blob([JSON.stringify({format:"discovery-up",version:2,items},null,2)],{type:"application/json"}));a.href=url;a.download="progression-discovery-up.json";a.click();URL.revokeObjectURL(url)}function restore(file){const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(x.format!=="discovery-up"||!x.items)throw 0;Object.entries(x.items).forEach(([k,v])=>{if(k.startsWith("discovery-up-")&&typeof v==="string")localStorage.setItem(k,v)});location.reload()}catch{alert("Ce fichier de sauvegarde n’est pas valide.")}};r.readAsText(file)}
function reward(target,msg,badge="+1"){const character=app.querySelector(".pulse");if(badge)target?.insertAdjacentHTML("beforeend",`<span class="point-float">${badge}</span>`);character?.classList.add("reward");navigator.vibrate?.(24);toast(msg);setTimeout(()=>{target?.querySelector(".point-float")?.remove();character?.classList.remove("reward")},950)}
function bind(){personalizeGoalRow();app.querySelectorAll("[data-movement]").forEach(b=>b.onclick=()=>b.dataset.movement==="nano"?openNano():toggleMovement(b.dataset.movement));app.querySelectorAll("[data-pillar]").forEach(b=>b.onclick=()=>{const d=data(),i=+b.dataset.pillar,on=d.pillars[i];d.pillars[i]=!on;if(!on)earn(d,"pillar-"+i);d.finished=false;write(new Date(),d);render();reward(app.querySelector(`[data-habit-row="${i}"]`),on?"Validation retirée":i===2?"Ton objectif progresse +1":"Ton pilier progresse +1",on?"":"+1")});app.querySelector(".open-bag")?.addEventListener("click",openBag);app.querySelector(".settings").onclick=settingsV14}

